function validate([nums, firstLen, secondLen]) {
  if (!Number.isInteger(firstLen) || !Number.isInteger(secondLen) || firstLen < 1 || secondLen < 1) return 'firstLen and secondLen are whole numbers of at least 1.';
  if (firstLen + secondLen > 1000) return 'firstLen + secondLen is at most 1000.';
  if (nums.length > 1000) return 'nums has at most 1000 values.';
  if (nums.length < firstLen + secondLen) return 'nums needs at least firstLen + secondLen values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each value is a whole number from 0 to 1000.';
  return null;
}

