function maxSumTwoNoOverlap(nums, firstLen, secondLen) {
  const n = nums.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + nums[i];
  }
  let bestFirst = 0;
  let bestSecond = 0;
  let best = 0;
  for (let end = firstLen + secondLen; end <= n; end++) {
    const firstBefore = prefix[end - secondLen] - prefix[end - secondLen - firstLen];
    const secondBefore = prefix[end - firstLen] - prefix[end - firstLen - secondLen];
    bestFirst = Math.max(bestFirst, firstBefore);
    bestSecond = Math.max(bestSecond, secondBefore);
    const secondLast = prefix[end] - prefix[end - secondLen];
    const firstLast = prefix[end] - prefix[end - firstLen];
    best = Math.max(best, bestFirst + secondLast, bestSecond + firstLast);
  }
  return best;
}

