function maxSumTwoNoOverlap(nums, firstLen, secondLen) {
  const n = nums.length;
  const total = (start, len) => {
    let s = 0;
    for (let k = start; k < start + len; k++) s += nums[k];
    return s;
  };
  let best = -1;
  for (let a = 0; a + firstLen <= n; a++) {
    for (let b = 0; b + secondLen <= n; b++) {
      const apart = a + firstLen <= b || b + secondLen <= a;
      if (apart) best = Math.max(best, total(a, firstLen) + total(b, secondLen));
    }
  }
  return best;
}

