  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(900, 1000);
    const firstLen = int(1, 300);
    const secondLen = int(1, 300);
    const nums = Array.from({ length: n }, () => int(0, 1000));
    return [nums, firstLen, secondLen];
  }
  const firstLen = int(1, 3);
  const secondLen = int(1, 3);
  const n = firstLen + secondLen + int(0, 6);
  const top = rand() < 0.2 ? 1000 : rand() < 0.5 ? 3 : 20;
  const nums = Array.from({ length: n }, () => int(0, top));
  return [nums, firstLen, secondLen];
}
